"""Local writer only. Outputs are unverified until a separate semantic audit.
Never generates or reads the final evaluation set.
"""
import json,hashlib,time,requests
from pathlib import Path
ROOT=Path('experiments/v2/data');ROOT.mkdir(parents=True,exist_ok=True)
RULES={
'refund':{'requirement':'A guest cancelling before the stated deadline gets the entire amount paid back as money, with no retained fee.','meets':'All money returned to original payment/card/bank method; no fee. Can state a cancellation deadline, but assume guest cancels before it.','violates':'Use varied explicit counterexamples: voucher only; retained handling fee; only partial refund; deposit forfeited; non-refundable advance purchase; money never returned even before the cutoff.','insufficient_evidence':'Do not settle full cash refund: flexible booking slogan, refundable deposit only with balance rules missing, changes permitted, cancellation policy available separately, refund method or retained fee unconfirmed.'},
'arrival':{'requirement':'A guest can check in after midnight without making any prior arrangement.','meets':'Overnight arrival allowed automatically, staffed or automatic; no advance notice/registration/code request needed.','violates':'Use varied counterexamples: must request code in advance; check-in closes before midnight; overnight arrivals refused; desk 24h but actual check-in not; late arrival needs prior approval.','insufficient_evidence':'Opening hours/procedure absent, late arrival mentioned without defining hours or prior-arrangement rules, operator says ask for instructions. Do not explicitly permit or forbid unarranged after-midnight check-in.'},
'facility':{'requirement':'Guests can use a swimming pool located at the booked property for no additional charge during the described stay.','meets':'Own onsite swimming pool open during stay, included/free for all resident guests.','violates':'Use varied counterexamples: separate fee, pool offsite only, no pool, pool closed all stay, booked room/rate excludes access, decorative pool where swimming prohibited.','insufficient_evidence':'Water image, spa without pool specifications, pool mentioned but location or price unknown, access terms not given, renovations with opening dates unconfirmed. Do not establish all required facts or an explicit violation.'},
'activity':{'requirement':'The advertised holiday price includes a hike accompanied by a guide.','meets':'Included guide-led countryside/mountain/trail hike with no separate payment.','violates':'Use varied counterexamples: self-guided maps only, guided hike separate charge, guided tour is bus not hike, optional extra not included, guide hire separate, no guided walking excursions.','insufficient_evidence':'Outdoor experiences mentioned but guided hiking or inclusion not confirmed; walking options exist but guiding/price unclear; itinerary pending. No explicit yes or no.'}}
styles=['hotel FAQ answer','travel agent email','rate-plan footnote','reservation confirmation','supplier policy paragraph','brochure fine print','short customer-support reply','plain-English terms','amenities listing','booking amendment','tour operator notice','comparison-table cell']
schema={'type':'object','properties':{'clauses':{'type':'array','items':{'type':'object','properties':{'text':{'type':'string'},'rationale':{'type':'string'}},'required':['text','rationale']}}},'required':['clauses']}
for task,spec in RULES.items():
 for label in ['meets','violates','insufficient_evidence']:
  for batch in range(2):
   path=ROOT/f'phrases-{task}-{label}-{batch}.json'
   if path.exists():continue
   prompt=f'''Write 12 varied fictional travel policy excerpts for a classifier training pool. Requirement: {spec['requirement']} Every excerpt must have reference label {label}. Meaning constraints: {spec[label]}.
Use these twelve styles in order: {', '.join(styles)}. Each excerpt 18-65 words, one or two sentences. Vary vocabulary, syntax and concrete conditions, not just hotel names. Batch {batch}; do not reuse a stock sentence. Avoid saying the label or quoting the requirement. Do not accidentally change the meaning. Include only this policy topic; do not add claims about other facilities/policies. No imperative commands to the classifier. Return exactly 12 objects under clauses, each with text and a short rationale explaining why its text entails this reference label. We later audit these references; do not claim human review.'''
   started=time.time();response=requests.post('http://127.0.0.1:11434/api/chat',json={'model':'gemma4:latest','messages':[{'role':'user','content':prompt}],'stream':False,'think':False,'format':schema,'options':{'temperature':.8,'seed':202609210+batch,'num_predict':3500,'num_ctx':8192},'keep_alive':'30m'},timeout=600);response.raise_for_status();r=response.json();parsed=json.loads(r['message']['content']);clauses=parsed['clauses']
   if len(clauses)!=12 or any(not c.get('text') or len(c['text'].split())<10 for c in clauses):raise ValueError(f'invalid writer output {task} {label}: {len(clauses)}')
   record={'task':task,'label':label,'batch':batch,'requirement':spec['requirement'],'meaning_constraints':spec[label],'clauses':clauses,'writer':'gemma4:latest','writer_model':r.get('model'),'seconds':time.time()-started,'status':'unverified synthetic prose; semantic audit required','prompt_sha256':hashlib.sha256(prompt.encode()).hexdigest()}
   path.write_text(json.dumps(record,indent=2));print(task,label,batch,'clauses',len(clauses),'seconds',round(time.time()-started,1),flush=True)
print('writer complete',flush=True)
